import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"配置说明","description":"","frontmatter":{},"headers":[],"relativePath":"database/redis/basic/config.md","filePath":"database/redis/basic/config.md"}`),a={name:`database/redis/basic/config.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to “配置说明”">​</a></h1><ul><li>参考文档：<a href="https://redis.com.cn/redis-configuration.html" target="_blank" rel="noreferrer">https://redis.com.cn/redis-configuration.html</a></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to “参数说明”">​</a></h2><ul><li><strong>daemonize</strong>： Redis 默认不是以守护进程的方式运行 daemonize no，可以通过该配置项修改，使用 yes 启用守护进程</li><li><strong>pidfile</strong>： 当 Redis 以守护进程方式运行时，Redis 默认会把 pid 写入 <code>/var/run/redis.pid</code> 文件。可以通过 pidfile 指定 <code>pidfile /var/run/redis.pid</code></li><li><strong>port</strong>：port 6379 指定 Redis 监听端口，默认端口为 6379</li><li><strong>bind</strong>： 监听的主机地址 bind 127.0.0.1</li><li><strong>timeout</strong>： <code>timeout 300</code> 当客户端闲置多长时间后关闭连接，如果指定为 0，表示关闭该功能</li><li><strong>loglevel</strong>：<code>loglevel verbose</code> 指定日志记录级别,默认为 <code>verbose</code>。Redis 总共支持四个级别：debug、verbose、notice、warning。</li><li><strong>logfile</strong>： <code>logfile stdout</code> 日志记录方式，默认为标准输出，如果配置 Redis 为守护进程方式运行，而这里又配置为日志记录方式为标准输出，则日志将会发送给 <code>/dev/null</code></li><li><strong>databases</strong>： <code>databases 16</code> 设置数据库的数量，默认数据库为 0，可以使用 <code>SELECT &lt;dbid&gt;</code>命令在连接上指定数据库 id</li><li><strong>save</strong>：<code>save &lt;seconds&gt; &lt;changes&gt; </code>指定在多长时间内，有多少次更新操作，就将数据同步到数据文件，可以多个条件配合, Redis 默认配置文件中提供了三个条件：<code>save 900 1</code>、<code>save 300 10</code>、<code>save 60 10000</code> ,分别表示 900 秒（15 分钟）内有 1 个更改，300 秒（5 分钟）内有 10 个更改以及 60 秒内有 10000 个更改。</li><li><strong>rdbcompression</strong>：<code>rdbcompression yes</code>指定存储至本地数据库时是否压缩数据，默认为 <code>yes</code>，Redis 采用 LZF 压缩，如果为了节省 CPU 时间，可以关闭该选项，但会导致数据库文件变的巨大 |</li><li><strong>dbfilename</strong>： <code>dbfilename dump.rdb</code> 指定本地数据库文件名，默认值为 <code>dump.rdb</code></li><li><strong>dir</strong>：<code>dir ./</code> 指定本地数据库存放目录</li><li><strong>slaveof</strong>： <code>slaveof &lt;masterip&gt; &lt;masterport&gt;</code> 设置当本机为 slave 服务时，设置 master 服务的 IP 地址及端口，在 Redis 启动时，它会自动从 master 进行数据同步</li><li><strong>masterauth</strong>： <code>masterauth &lt;master-password&gt; master</code> 服务设置了密码保护时，slave 服务连接 master 的密码</li><li><strong>requirepass</strong>： <code>requirepass foobared</code> 设置 Redis 连接密码，如果配置了连接密码，客户端在连接 Redis 时需要通过 <code>AUTH &lt;password&gt;</code>命令提供密码，默认关闭</li><li><strong>maxclients</strong>：<code>maxclients 128</code> 设置同一时间最大客户端连接数，默认无限制，Redis 可以同时打开的客户端连接数为 Redis 进程可以打开的最大文件描述符数，如果设置 maxclients 0，表示不作限制。当客户端连接数到达限制时，Redis 会关闭新的连接并向客户端返回 max number of clients reached 错误信息</li><li><strong>maxmemory</strong>： <code>maxmemory &lt;bytes&gt;</code> 指定 Redis 最大内存限制，Redis 在启动时会把数据加载到内存中，达到最大内存后，Redis 会先尝试清除已到期或即将到期的 Key，当此方法处理后，仍然到达最大内存设置，将无法再进行写入操作，但仍然可以进行读取操作。Redis 新的 vm 机制，会把 Key 存放内存，Value 会存放在 swap 区</li><li><strong>appendonly</strong>： <code>appendonly no</code> 指定是否在每次更新操作后进行日志记录，Redis 在默认情况下是异步的把数据写入磁盘，如果不开启，可能会在断电时导致一段时间内的数据丢失。因为 redis 本身同步数据文件是按上面 save 条件来同步的，所以有的数据会在一段时间内只存在于内存中。默认为 <code>no</code></li><li><strong>appendfilename</strong>： <code>appendfilename appendonly.aof</code> 指定更新日志文件名，默认为 <code>appendonly.aof</code></li><li><strong>appendfsync</strong>：<code> appendfsync everysec</code> 指定更新日志条件，共有 3 个可选值：no：表示等操作系统进行数据缓存同步到磁盘（快）; always：表示每次更新操作后手动调用 fsync() 将数据写到磁盘（慢，安全）; everysec：表示每秒同步一次（折衷，默认值）</li></ul>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};